import React, { useState, useRef, useEffect } from 'react';
import styles from './index-react.module.css';
import { useNavigate } from 'react-router-dom';
import AttachFileIcon from '@mui/icons-material/AttachFile';
import MicIcon from '@mui/icons-material/Mic';
import { callApi } from '../api/client';

export default function Home() {
  const [queryInput, setQueryInput] = useState('');
  const [file, setFile] = useState(null);
  const navigate = useNavigate();
  const inputRef = useRef(null);

  const recognitionRef = useRef(null);
  const [isListening, setIsListening] = useState(false);
  const [micError, setMicError] = useState('');
  const [micReady, setMicReady] = useState(false);

  // Initialize SpeechRecognition
  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setMicError('Voice input not supported by this browser.');
      return setMicReady(false);
    }

    // Check microphone permission
    if (navigator.permissions?.query) {
      navigator.permissions.query({ name: 'microphone' }).then((ps) => {
        if (ps.state === 'denied') {
          setMicError('Mic permission denied.');
          setMicReady(false);
        }
        ps.onchange = () => {
          if (ps.state === 'denied') {
            setMicError('Mic permission denied.');
            setMicReady(false);
            recognitionRef.current?.stop();
          } else {
            setMicError('');
          }
        };
      }).catch(err => console.error('Mic permission query error:', err));
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => { setIsListening(true); setMicError(''); };
    recognition.onend = () => { setIsListening(false); };

    recognition.onresult = (e) => {
      setQueryInput(e.results[0][0].transcript);
    };

    recognition.onerror = (e) => {
      let msg = `Speech error: ${e.error}`;
      switch (e.error) {
        case 'not-allowed':
        case 'service-not-allowed': msg = 'Mic permission denied.'; break;
        case 'no-speech': msg = 'No speech detected.'; break;
        case 'audio-capture': msg = 'Mic hardware error.'; break;
        case 'network': msg = 'Network error.'; break;
      }
      setMicError(msg);
      setIsListening(false);
    };

    recognitionRef.current = recognition;
    setMicReady(true);
    setMicError('');

    return () => { recognitionRef.current?.abort(); };
  }, []);

  const handleFileChange = (e) => {
    const uploaded = e.target.files?.[0] || null;
    setFile(uploaded);
    if (uploaded) setMicError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isListening && recognitionRef.current) {
      recognitionRef.current.stop();
    }

    const trimmed = queryInput.trim();
    if (!trimmed) {
      setMicError('Please enter a query or attach a CSV file.');
      return;
    }

    // If no file, redirect to RAG route (full page load)
    if (!file) {
      const q = encodeURIComponent(trimmed);
      window.location.href = `/rag?query=${q}`;
      return;
    }

    // Otherwise, handle CSV -> conversation flow
    const formData = new FormData();
    formData.append('queryInput', trimmed);
    formData.append('file-upload', file);

    try {
      const data = await callApi('home', 'POST', formData);
      if (data.conversation) {
        navigate('/conversation', { state: { conversation: data.conversation } });
      } else {
        console.error('API response missing conversation data:', data);
        setMicError('Failed to process uploaded file.');
      }
    } catch (err) {
      console.error('API call failed:', err);
      setMicError('Network/server error.');
    }
  };

  const handleVoiceInput = () => {
    if (!micReady || !recognitionRef.current) {
      if (!micError) setMicError('Voice unavailable.');
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      try {
        setQueryInput('');
        setFile(null);
        setMicError('');
        recognitionRef.current.start();
      } catch (error) {
        console.error('Mic start error:', error);
        setMicError('Could not start mic.');
        setIsListening(false);
      }
    }
  };

  const micButtonDisabled = !micReady;

  const autoMLClassName = `${styles.autoML || ''} ${isListening ? styles.listening : ''}`.trim();
  const micButtonClassName = `${styles.iconButton || ''} ${isListening ? styles.active : ''}`.trim();

  return (
    <div className={autoMLClassName}>
      <div className={styles.container}>
        <div className={styles.header}>
          <p>Bonjour</p>
          <h1>How Can We Help You?</h1>
        </div>

        <form onSubmit={handleSubmit}>
          <div className={styles.inputArea}>
            <div className={styles.inputWrapper}>
              <input
                type="text"
                ref={inputRef}
                value={queryInput}
                onChange={e => setQueryInput(e.target.value)}
                placeholder={isListening ? 'Listening...' : 'Describe Your Problem'}
                required
                disabled={isListening}
              />
              <div className={styles.inputIcons}>
                <label
                  htmlFor="file-upload"
                  className={styles.iconButton}
                  aria-disabled={isListening}
                  title="Attach file"
                  style={isListening ? { pointerEvents: 'none', opacity: 0.5 } : {}}
                >
                  <AttachFileIcon fontSize="inherit" />
                </label>
                <input
                  id="file-upload"
                  name="file-upload"
                  type="file"
                  hidden
                  onChange={handleFileChange}
                  disabled={isListening}
                />
                <button
                  type="button"
                  onClick={handleVoiceInput}
                  className={micButtonClassName}
                  disabled={micButtonDisabled || isListening}
                  title={micError || (!micReady ? 'Voice input unavailable' : isListening ? 'Stop Listening' : 'Start Voice Input')}
                >
                  <MicIcon fontSize="inherit" />
                </button>
              </div>
            </div>

            {file && !micError && !isListening && (
              <p className={styles.fileDisplay}>File: {file.name}</p>
            )}
            {isListening && (
              <p className={`${styles.statusDisplay || ''} ${styles.listeningIndicator || ''}`.trim()}>🎙 Listening...
              </p>
            )}
            {micError && (
              <p className={`${styles.statusDisplay || ''} ${styles.errorMessage || ''}`.trim()}>⚠ {micError}</p>
            )}
          </div>

          <button type="submit" className={styles.actionButton} disabled={isListening}>
            Start Analysis
          </button>
        </form>
      </div>
    </div>
  );
}
